const nav=[{label:"operations",items:[["dashboard","◫"],["pointOfSale","▣"],["sales","↗"],["prescriptions","⊙"]]},{label:"catalog",items:[["inventory","▤"],["products","⊞"],["purchasing","⇄"],["customers","♙"],["suppliers","♧"]]},{label:"management",items:[["reports","▥"],["users","♙"],["roles","◇"],["masterData","☷"],["settings","⚙"]]}];
const pageTitle={dashboard:"overview",products:"productsTitle",inventory:"inventoryTitle",sales:"salesTitle",prescriptions:"prescriptionsTitle",purchasing:"purchasingTitle",customers:"customersTitle",suppliers:"suppliersTitle",users:"adminUsersTitle",roles:"rolesTitle",masterData:"standardTitle",reports:"reportTitle",pointOfSale:"pointOfSaleTitle",settings:"settingsTitle",help:"helpTitle"};
let lang=localStorage.getItem("pbm-lang")||"en",data=readData(),page="dashboard",toastTimer;
function readData(){try{return {...seed,...JSON.parse(localStorage.getItem("pbm-data")||"{}")}}catch{return structuredClone(seed)}}
function save(){localStorage.setItem("pbm-data",JSON.stringify(data))}function t(k){return tr[lang][k]||tr.en[k]||k}function esc(x){return String(x).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c])}
function money(n){const v=new Intl.NumberFormat(lang==="ar"?"ar-EG":"en-EG",{maximumFractionDigits:n%1?2:0}).format(n);return lang==="ar"?`${v} ${t("egyptianPound")}`:`EGP ${v}`}
function localeSet(value){lang=value;localStorage.setItem("pbm-lang",lang);document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";document.body.classList.toggle("rtl",lang==="ar");render()}
function navRender(){const el=document.getElementById("mainNav");el.innerHTML=nav.map(group=>`<div class="nav-heading">${t(group.label)}</div>${group.items.map(([key,icon])=>`<button class="nav-item ${page===key?"active":""}" data-page="${key}"><span class="nav-icon">${icon}</span><span>${t(key)}</span>${key==="inventory"?'<span class="nav-badge">3</span>':""}</button>`).join("")}`).join("");el.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll(".sidebar-bottom [data-page]").forEach(b=>b.onclick=()=>go(b.dataset.page))}
function go(p){page=p;document.getElementById("sidebar").classList.remove("open");document.querySelector(".mobile-overlay")?.classList.remove("visible");render()}
function render(){navRender();document.getElementById("pageCrumb").textContent=t(pageTitle[page]||page);document.getElementById("languageButton").textContent=lang==="en"?t("arabic"):t("english");document.querySelectorAll("[data-i18n]").forEach(e=>e.textContent=t(e.dataset.i18n));document.querySelectorAll("[data-i18n-placeholder]").forEach(e=>e.placeholder=t(e.dataset.i18nPlaceholder));document.getElementById("pageContent").innerHTML=page==="dashboard"?dashboard():view(page);document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll("[data-action]").forEach(b=>b.onclick=()=>act(b.dataset.action));document.querySelectorAll("[data-toast]").forEach(b=>b.onclick=e=>{e.preventDefault();notify(`${t("seeRecords")}: ${b.dataset.toast}`)});document.querySelectorAll("[data-table-search]").forEach(i=>i.oninput=()=>filterRows(i.value));document.querySelector("[data-pos-search]")?.addEventListener("input",e=>posResults(e.target.value));if(page==="pointOfSale")posResults("")}
function heading(title,sub,button=""){return `<div class="page-heading"><div><p class="eyebrow">${t("branchName")}</p><h1>${t(title)}</h1><p class="subheading">${t(sub)}</p></div>${button}</div>`}function btn(label,action,icon="+"){return `<button class="button button-primary" data-action="${action}"><span class="button-icon">${icon}</span><span class="button-label">${t(label)}</span></button>`}
function dashboard(){const total=data.sales.reduce((s,x)=>s+x.amount,0),low=data.products.filter(x=>x.qty<=x.reorder).length;const metrics=[["netSales",money(total),"↑ 12.8%","vsYesterday","↗"],["transactions","48","↑ 8.2%","completedToday","▣"],["lowStock",String(low).padStart(2,"0"),"3","needRestock","▤"],["expiringSoon","07","2","within30","◷"]];return `${heading("greeting","dashboardSub",btn("newSale","new-sale"))}<div class="metric-grid">${metrics.map((m,i)=>`<article class="metric-card"><div class="metric-top"><span>${t(m[0])}</span><span class="metric-icon">${m[4]}</span></div><div class="metric-value">${m[1]}</div><div class="metric-foot"><span class="${i<2?"trend-up":"trend-down"}">${m[2]}</span><span>${t(m[3])}</span></div></article>`).join("")}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">${t("salesOverview")}</h2><div class="panel-subtitle">${t("last7Days")}</div></div><div class="chart-legend"><span class="legend-item"><i class="legend-dot dark"></i>${t("revenue")}</span><span class="legend-item"><i class="legend-dot"></i>${t("target")}</span><select class="select-quiet"><option>${t("thisWeek")}</option></select></div></div>${chart()}</section><section class="panel"><div class="panel-header"><div><h2 class="panel-title">${t("stockAlerts")}</h2><div class="panel-subtitle">${low} ${t("lowStock").toLowerCase()}</div></div><button class="table-link" data-page="inventory">${t("viewInventory")}</button></div><div class="activity-list">${data.products.filter(p=>p.qty<=p.reorder).slice(0,4).map((p,i)=>`<div class="activity-item"><span class="activity-symbol ${i===2?"rose":"amber"}">!</span><span class="activity-copy"><strong>${esc(p.name)}</strong><small>${t(i===2?"expires":"reorderSoon")}: ${esc(p.batch.split(" / ")[1])}</small></span><span class="activity-qty">${p.qty} ${t("unitsLeft")}</span></div>`).join("")}</div></section></div><section class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">${t("recentSales")}</h2><div class="panel-subtitle">${t("latestTransactions")}</div></div><button class="table-link" data-page="sales">${t("viewAll")}</button></div>${salesTable(data.sales.slice(0,5))}</section>`}
function chart(){const days=lang==="ar"?["الأربعاء","الخميس","الجمعة","السبت","الأحد","الاثنين","الثلاثاء"]:["Wed","Thu","Fri","Sat","Sun","Mon","Tue"],values=[53,70,47,81,62,92,72];return `<div class="chart-wrap"><div class="chart-grid">${["12k","8k","4k","0"].map(x=>`<div class="chart-grid-line"><span>${x}</span></div>`).join("")}<div class="bars">${values.map((h,i)=>`<div class="bar-group"><i class="bar" style="height:${h-13}%"></i><i class="bar ${i===5?"highlight":""}" style="height:${h}%"></i><span class="bar-label">${days[i]}</span></div>`).join("")}</div></div></div>`}
function badge(s){const key=["paid","pending","received","draft","inactive","low"].includes(s)?s:"active";return `<span class="status status-${s}">${t(key)}</span>`}
function salesTable(rows){return `<div class="table-wrap"><table><thead><tr>${["invoice","customer","cashier","amount","status","action"].map(x=>`<th>${t(x)}</th>`).join("")}</tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.id)}</strong></td><td>${esc(s.customer)}</td><td>${esc(s.cashier)}</td><td>${money(s.amount)}</td><td>${badge(s.status)}</td><td><a class="table-link" href="#${s.id}" data-toast="${esc(s.id)}">${t("seeRecords")}</a></td></tr>`).join("")}</tbody></table></div>`}
function toolbar(action,label){return `<div class="page-toolbar"><div class="toolbar-left"><input class="table-search" type="search" placeholder="${t("searchTable")}" data-table-search></div><div class="toolbar-right"><button class="button button-quiet" data-action="filter"><span class="button-icon">☷</span><span class="button-label">${t("filter")}</span></button>${btn(label,action)}</div></div>`}
function table(headers,rows){return `<section class="panel table-panel"><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${t(h)}</th>`).join("")}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join(""):`<tr><td colspan="${headers.length}"><div class="empty-state"><strong>${t("noResults")}</strong>${t("noResultsSub")}</div></td></tr>`}</tbody></table></div></section>`}
function catalog(inventory){const rows=data.products.map(p=>[`<strong>${esc(p.name)}</strong><div class="panel-subtitle">${esc(p.category)}</div>`,p.code,`${p.qty} ${t("units")}`,`${p.reorder} ${t("units")}`,esc(p.batch),money(p.price),badge(p.status)]);return `${heading(inventory?"inventoryTitle":"productsTitle",inventory?"inventorySub":"productsSub",inventory?"":btn("addProduct","add-product"))}${toolbar("filter","filter")}${table(["product","code","qty","reorder","batch","price","stockStatus"],rows)}`}
function userView(){return `${heading("adminUsersTitle","adminIntro",btn("users","new-user"))}<div class="metric-grid"><article class="metric-card"><div class="metric-top">${t("staffUsers")}</div><div class="metric-value">${data.users.filter(u=>u.status==="active").length}</div><div class="metric-foot">${t("usersActive")}</div></article><article class="metric-card"><div class="metric-top">${t("roles")}</div><div class="metric-value">4</div><div class="metric-foot">${t("configured")}</div></article></div>${toolbar("new-user","users")}${table(["staffUsers","assignedRoles","branch","lastLogin","status","action"],data.users.map(u=>[`<strong>${esc(u.name)}</strong><div class="panel-subtitle">${esc(u.email)}</div>`,t(u.role),u.branch,u.last,badge(u.status),`<a class="table-link" data-toast="${esc(u.name)}">${t("manage")}</a>`]))}`}
function rolesView(){const roles=["administrator","branchManager","pharmacist","cashierRole"],desc=lang==="ar"?["إدارة كاملة للفروع والمستخدمين والإعدادات","إدارة عمليات الفرع والمخزون والتقارير","صرف الأدوية وإدارة الوصفات والمخزون","تسجيل المبيعات وإدارة ملفات العملاء"]:["Full access to branches, users and configuration","Manage branch operations, inventory and reports","Dispense medicines and manage prescriptions","Record sales and manage customer profiles"];return `${heading("rolesTitle","adminIntro",btn("roles","new-role"))}<div class="section-grid">${roles.map((r,i)=>`<article class="section-card"><h3>${t(r)}</h3><p>${desc[i]}</p><div class="section-card-foot">${[4,3,5,2][i]} ${t("permissions")}</div></article>`).join("")}</div><section class="panel table-panel" style="margin-top:14px"><div class="panel-header"><h2 class="panel-title">${t("permissionMatrix")}</h2></div>${table(["permissions",...roles],(lang==="ar"?["المستخدمون","الكتالوج","المبيعات","التقارير"]:["Users","Catalog","Sales","Reports"]).map((x,i)=>[x,"✓","✓","✓",i===2?"—":"✓"]))}</section>`}
function masterView(){const names=lang==="ar"?["فئات الأدوية","الموردون","طرق الدفع","الضرائب","الجرعات والأشكال","الفروع","وحدات القياس","أسباب الإرجاع","إعدادات الولاء"]:["Medicine categories","Suppliers","Payment methods","Tax groups","Dosage forms","Branches","Units of measure","Return reasons","Loyalty settings"],desc=lang==="ar"?["تصنيف الأدوية وتنظيم الكتالوج.","قوائم الموردين وشروط التوريد.","النقدي والبطاقات والمحافظ.","إعدادات ضريبة القيمة المضافة.","الأقراص والكبسولات والشراب.","إعداد بيانات فروع الصيدلية.","العبوات والشرائط والوحدات.","توحيد أسباب إرجاع المبيعات.","قواعد النقاط ومكافآت العملاء."]:["Organize and classify the medicine catalog.","Supplier directory and payment terms.","Cash, cards and digital wallets.","Configure Egyptian VAT rates.","Tablets, capsules, syrup and more.","Configure pharmacy branch records.","Packs, strips and individual units.","Standardize sales return reasons.","Customer points and reward rules."];return `${heading("standardTitle","standardSub")}<div class="section-grid">${names.map((x,i)=>`<article class="section-card"><h3>${x}</h3><p>${desc[i]}</p><div class="section-card-foot"><a class="table-link" data-toast="${x}">${t("manage")} →</a></div></article>`).join("")}</div>`}
function simpleCards(title,sub,cards){return `${heading(title,sub)}<div class="section-grid">${cards.map(c=>`<article class="section-card"><h3>${c[0]}</h3><p>${c[1]}</p><div class="section-card-foot"><a class="table-link" data-toast="${c[0]}">${t("manage")} →</a></div></article>`).join("")}</div>`}
function view(p){if(p==="products"||p==="inventory")return catalog(p==="inventory");if(p==="users")return userView();if(p==="roles")return rolesView();if(p==="masterData")return masterView();if(p==="sales")return `${heading("salesTitle","salesSub")}${toolbar("export","export")}${salesTable(data.sales)}`;if(p==="prescriptions")return `${heading("prescriptionsTitle","prescriptionsSub")}${toolbar("new-prescription","newSale")}${table(["prescriptionRef","customer","prescribedBy","created","status"],data.prescriptions.map(x=>[`<strong>${x.id}</strong>`,esc(x.customer),esc(x.doctor),x.date,badge(x.status)]))}`;if(p==="purchasing")return `${heading("purchasingTitle","purchasingSub")}${toolbar("new-purchase","newProduct")}${table(["purchaseNo","supplierName","created","expected","amount","status"],data.purchases.map(x=>[`<strong>${x.id}</strong>`,x.supplier,x.date,x.expected,money(x.amount),badge(x.status)]))}`;if(p==="customers")return `${heading("customersTitle","customersSub")}${toolbar("new-customer","customers")}${table(["customer","code","transactions","amount","role"],data.customers.map((x,i)=>[`<strong>${esc(x.name)}</strong><div class="panel-subtitle">${x.phone}</div>`,`CUS-${1042+i}`,x.visits,money(x.spend),`${x.points} pts`]))}`;if(p==="suppliers")return `${heading("suppliersTitle","suppliersSub")}${toolbar("new-supplier","suppliers")}${table(["supplier","customer","cashier","role","status"],data.suppliers.map(x=>[`<strong>${esc(x.name)}</strong>`,x.email,x.phone,x.terms,badge("active")]))}`;if(p==="pointOfSale")return `${heading("pointOfSaleTitle","posIntro")}<section class="panel"><div class="panel-header"><h2 class="panel-title">${t("pointOfSaleTitle")}</h2></div><div style="padding:22px;display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap"><strong>${t("productsTitle")}<div class="panel-subtitle">${data.products.length} ${t("activeProducts")}</div></strong><input class="table-search" placeholder="${t("searchPlaceholder")}" data-pos-search></div><div class="activity-list" id="posResults"></div></section>`;if(p==="reports")return `${heading("reportTitle","reportSub")}${chart()}`;if(p==="settings")return simpleCards("settingsTitle","settingsSub",lang==="ar"?[["بيانات الفرع","العنوان وساعات العمل وبيانات الاتصال."],["إعدادات الفواتير","تنسيق الفاتورة والرقم الضريبي."],["اللغة والعملة","العربية أو الإنجليزية والجنيه المصري."]]:[["Branch profile","Address, opening hours and contact details."],["Invoice preferences","Receipt format and tax registration details."],["Language & currency","Arabic or English, with Egyptian pound pricing."]]);if(p==="help")return simpleCards("helpTitle","helpSub",[["Getting started","Set up your team, branch catalog, suppliers and opening stock."],["Contact support","Reach the Pharmacy by Me support team for help."]]);return ""}
function filterRows(q){const term=q.trim().toLowerCase();document.querySelectorAll(".table-panel tbody tr").forEach(r=>r.hidden=term&&!r.textContent.toLowerCase().includes(term))}
function act(a){if(a==="add-product")return modal();if(a==="new-user")return userModal();if(a==="new-sale"){go("pointOfSale");notify(t("posIntro"));return}if(a==="export"){exportCsv();return}if(a==="filter"){notify(t("filter"));return}const key={"new-role":"roles","new-purchase":"purchasing","new-prescription":"prescriptions","new-customer":"customers","new-supplier":"suppliers"}[a];if(key)notify(`${t("manage")} ${t(key)}`)}
function userModal(){const root=document.getElementById("modalBackdrop"),labels=lang==="ar"?{title:"إضافة مستخدم",name:"الاسم الكامل",email:"البريد الإلكتروني",role:"الدور",branch:"الفرع",save:"حفظ المستخدم"}:{title:"Add staff user",name:"Full name",email:"Email address",role:"Role",branch:"Branch",save:"Save user"};root.hidden=false;root.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-heading"><h2>${labels.title}</h2><button class="icon-button" data-close>×</button></div><form class="modal-body"><div class="form-field"><label>${labels.name}</label><input name="name" required></div><div class="form-field"><label>${labels.email}</label><input name="email" type="email" required></div><div class="form-field"><label>${labels.role}</label><select name="role"><option value="pharmacist">${t("pharmacist")}</option><option value="cashierRole">${t("cashierRole")}</option><option value="branchManager">${t("branchManager")}</option><option value="administrator">${t("administrator")}</option></select></div><div class="form-field"><label>${labels.branch}</label><select name="branch"><option>Zamalek</option><option>Nasr City</option><option>Maadi</option></select></div><div class="modal-actions"><button type="button" class="button button-quiet" data-close>${t("cancel")}</button><button class="button button-primary">${labels.save}</button></div></form></div>`;root.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>root.hidden=true);root.onclick=e=>{if(e.target===root)root.hidden=true};root.querySelector("form").onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);data.users.unshift({name:f.get("name"),email:f.get("email"),role:f.get("role"),branch:f.get("branch"),last:"Never",status:"active"});save();root.hidden=true;render();notify(t("saved"))};root.querySelector("input").focus()}
function modal(){const root=document.getElementById("modalBackdrop");root.hidden=false;root.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-heading"><h2>${t("addProduct")}</h2><button class="icon-button" data-close>×</button></div><form class="modal-body" id="productForm"><div class="form-field"><label>${t("productName")}</label><input name="name" required></div><div class="form-field"><label>${t("barcode")}</label><input name="code" inputmode="numeric" required></div><div class="form-field"><label>${t("category")}</label><select name="category"><option>Pain relief</option><option>Antibiotics</option><option>Vitamins</option><option>Cold & flu</option><option>Other</option></select></div><div class="form-field"><label>${t("price")}</label><input name="price" type="number" min="0" step=".01" required></div><div class="form-field"><label>${t("quantity")}</label><input name="qty" type="number" min="0" value="0" required></div><div class="modal-actions"><button type="button" class="button button-quiet" data-close>${t("cancel")}</button><button class="button button-primary">${t("saveProduct")}</button></div></form></div>`;root.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>root.hidden=true);root.onclick=e=>{if(e.target===root)root.hidden=true};root.querySelector("form").onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),qty=Number(f.get("qty"));data.products.unshift({name:f.get("name"),code:f.get("code"),category:f.get("category"),price:Number(f.get("price")),qty,reorder:10,batch:"New batch / —",supplier:"—",cost:0,status:qty<10?"low":"active"});save();root.hidden=true;render();notify(t("saved"))};root.querySelector("input").focus()}
function exportCsv(){const body=["Invoice,Customer,Cashier,Amount,Status",...data.sales.map(s=>[s.id,s.customer,s.cashier,s.amount,s.status].map(v=>`"${String(v).replaceAll('"','""')}"`).join(","))].join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([body],{type:"text/csv"}));a.download="pharmacy-sales.csv";a.click();URL.revokeObjectURL(a.href);notify(t("export"))}
function posResults(query){const target=document.getElementById("posResults");if(!target)return;const q=query.trim().toLowerCase();target.innerHTML=data.products.filter(p=>`${p.name} ${p.code}`.toLowerCase().includes(q)).slice(0,5).map((p,i)=>`<div class="activity-item"><span class="activity-symbol ${i%2?"green":"amber"}">+</span><span class="activity-copy"><strong>${esc(p.name)}</strong><small>${p.code} · ${p.qty} ${t("units")}</small></span><span class="activity-qty">${money(p.price)}</span><button class="button button-quiet" data-cart="${esc(p.code)}">+</button></div>`).join("");target.querySelectorAll("[data-cart]").forEach(b=>b.onclick=()=>notify(`${t("saved")}: ${data.products.find(p=>p.code===b.dataset.cart)?.name}`))}
function notify(message){const el=document.getElementById("toast");el.textContent=message;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),2200)}
document.getElementById("languageButton").onclick=()=>localeSet(lang==="en"?"ar":"en");document.getElementById("menuButton").onclick=()=>{const side=document.getElementById("sidebar");side.classList.toggle("open");let overlay=document.querySelector(".mobile-overlay");if(!overlay){overlay=document.createElement("div");overlay.className="mobile-overlay";document.body.append(overlay);overlay.onclick=()=>{side.classList.remove("open");overlay.classList.remove("visible")}}overlay.classList.toggle("visible",side.classList.contains("open"))};document.getElementById("globalSearch").oninput=e=>{const q=e.target.value.trim().toLowerCase();if(q){const found=data.products.some(p=>`${p.name} ${p.code}`.toLowerCase().includes(q));go(found?"products":"sales");const input=document.querySelector("[data-table-search]");if(input){input.value=q;filterRows(q)}}};document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();document.getElementById("globalSearch").focus()}if(e.key==="Escape")document.getElementById("modalBackdrop").hidden=true});localeSet(lang);
